    "base": "audit/lang-c-data-members",
    "title": "fix(sem): extract C++ in-class method declarations",
    "status": "open",
    "phase": "reviewing",
    "author": {
      "id": "01KSK3QAE64QAADZ4Z86DY4771",
      "login": "suhaanthayyil"
