// TestSignatureNamesQualifiedMethodUsesTokenBoundaries pins the qualified-name match
// against both directions of a raw substring test.
//
// Matching `Container::Name` with strings.Contains was wrong twice over. It matched too
// much -- `BA::foo` contains `A::foo`, so an unrelated class's definition was accepted as
// a declaration's out-of-line body and emitted a CALLS edge to the wrong function -- and
// too little, because a template definition is spelled `A<T>::foo` and never contains the
// bare text, leaving those calls resolved to the bodyless declaration whose callers the
// lookup exists to redirect.
func TestSignatureNamesQualifiedMethodUsesTokenBoundaries(t *testing.T) {
	t.Parallel()

	for _, testCase := range []struct {
		name      string
		signature string
		container string
		method    string
		want      bool
	}{
		{"plain qualified definition", "int A::foo(int x)", "A", "foo", true},
		{"template definition qualifies through its arguments", "int A<T>::foo(int x)", "A", "foo", true},
		{"a longer class name is not this class", "int BA::foo(int x)", "A", "foo", false},
		{"a longer method name is not this method", "int A::foobar(int x)", "A", "foo", false},
		{"a different class does not match", "int B::foo(int x)", "A", "foo", false},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			t.Parallel()
			if got := signatureNamesQualifiedMethod(testCase.signature, testCase.container, testCase.method); got != testCase.want {
				t.Fatalf("signatureNamesQualifiedMethod(%q, %q, %q) = %v, want %v",
					testCase.signature, testCase.container, testCase.method, got, testCase.want)
			}
		})
	}
}

func TestFSharpCustomOperatorContainingADollarIsNotACall(t *testing.T) {
	// `$` is an op-char in F#'s own lexer (`let op_char = '!'|'$'|'%'|...`), so
	// `$|>` is ONE operator token exactly as `+|>` is. Omitting `$` from the
	// scanner's op-char set stopped the walk that finds the token's real extent:
	// `value $|> helper` was read as a plain forward pipe and fabricated a call
	// to helper, which is the custom operator's right operand.
	repo := t.TempDir()
	writeFile(t, repo, "src/Dollars.fs", `module Dollars

let helper (value: int) = value + 1

let combine (a: int) (b: int) = a + b

let ($|>) (left: int) (right: int) = left + right

let custom (value: int) = value $|> helper

let piped (a: int) (b: int) = (a, b) ||> combine
`)

	snapshot, err := BuildProviderSnapshotWithOptions(t.Context(), repo, "test-version", ProviderSnapshotOptions{Worktree: true})
	if err != nil {
		t.Fatal(err)
}

// uniqueMethodByShortName returns the sole method whose short name matches, if
// exactly one method (across the workspace) carries that name. Used as a
// last-resort receiver.method() resolver when the receiver type is unknown.
// signatureNamesQualifiedMethod reports whether signature writes
// `Container::Name` as a whole qualified name.
//
// A raw substring test is wrong in both directions. It matches too much --
// `BA::foo` contains `A::foo`, so an unrelated class's definition was accepted
// as the out-of-line body and produced a false CALLS edge -- and too little,
// because a template definition is spelled `A<T>::foo` and never contains the
// bare `A::foo` at all, leaving those calls pointed at the bodyless
// declaration. Both are the same mistake: treating a qualified name as text
// rather than as tokens.
func signatureNamesQualifiedMethod(signature, container, name string) bool {
	for offset := 0; ; {
		index := strings.Index(signature[offset:], container)
		if index < 0 {
			return false
		}
		start := offset + index
		offset = start + len(container)
		// The container must start a token: `BA::foo` must not match `A::foo`.
		if start > 0 && isIdentifierByte(signature[start-1]) {
			continue
		}
		rest := signature[offset:]
		// A template definition qualifies through its argument list
		// (`A<T>::foo`), which is part of the same name. The list closes at the
		// MATCHING `>`, not the first one seen: `A<std::vector<T>>::foo` and
		// `A<std::vector<T> >::foo` both close the outer list at the second, so
		// cutting at the first left `>::foo` behind and rejected the definition
		// -- every nested-template class's out-of-line body stayed disconnected
		// from its callers. An argument list that never closes is not a
		// qualification at all, so that occurrence is skipped rather than
		// accepted on a truncated remainder.
		if strings.HasPrefix(rest, "<") {
			after, closed := skipBalancedAngles(rest)
			if !closed {
				continue
			}
			rest = after
		}
		if !strings.HasPrefix(rest, "::"+name) {
			continue
		}
		// The name must end a token, so `A::foobar` does not match `A::foo`.
		after := rest[len("::"+name):]
		if after == "" || !isIdentifierByte(after[0]) {
			return true
		}
	}
}

// skipBalancedAngles returns the text following the template argument list that
// begins at text[0] == '<', and whether that list was closed. Angle brackets
// nest, so the list ends at the bracket that matches the opening one -- the
// SECOND `>` of `<std::vector<T>>` -- and a depth count is the only way to find
// it. `>>` is two ordinary `>` bytes here, so the C++11 spelling and the
// spaced-out `> >` both close at the same depth.
func skipBalancedAngles(text string) (string, bool) {
	depth := 0
	for i := 0; i < len(text); i++ {
		switch text[i] {
		case '<':
			depth++
		case '>':
			depth--
			if depth == 0 {
				return text[i+1:], true
			}
		}
	}
	return text, false
}

