const patch = "*** Begin Patch
*** Update File: /Users/thomi/.codex/worktrees/c68d/entire-graph/internal/sem/model.go
@@
-	// cPlusPlusOwner is the declaration's full lexical C++ owner spelling
-	// (`acct::Outer::Ledger`). Graph QualifiedName intentionally remains based
-	// on the immediate container for stable IDs, so out-of-line definition
-	// matching carries this separately.
-	cPlusPlusOwner string
+	// cPlusPlusOwners are the declaration's legal lexical C++ owner spellings
+	// (`acct::Outer::Ledger`), including bounded aliases produced by omitting
+	// inline namespaces. Graph QualifiedName intentionally remains based on the
+	// immediate container for stable IDs, so definition matching carries these
+	// separately.
+	cPlusPlusOwners []string
*** Update File: /Users/thomi/.codex/worktrees/c68d/entire-graph/internal/sem/provider.go
@@
-	// cPlusPlusOwner carries the full lexical namespace/class owner used only to
-	// match a bodyless declaration to its out-of-line C++ definition.
-	cPlusPlusOwner string
+	// cPlusPlusOwners carry the legal lexical namespace/class owners used only
+	// to match a bodyless declaration to its out-of-line C++ definition.
+	cPlusPlusOwners []string
@@
-			cPlusPlusOwner: entity.cPlusPlusOwner,
+			cPlusPlusOwners: append([]string(nil), entity.cPlusPlusOwners...),
@@
-	container := declaration.cPlusPlusOwner
-	if container == "" {
-		container = containerName(declaration.QualifiedName)
+	owners := declaration.cPlusPlusOwners
+	if len(owners) == 0 {
+		owners = []string{containerName(declaration.QualifiedName)}
 	}
@@
-		if candidate.Name != declaration.Name || !signatureNamesQualifiedMethod(candidate.Signature, container, declaration.Name) {
+		if candidate.Name != declaration.Name {
 			continue
 		}
+		ownerMatches := false
+		for _, owner := range owners {
+			if owner != "" && signatureNamesQualifiedMethod(candidate.Signature, owner, declaration.Name) {
+				ownerMatches = true
+				break
+			}
+		}
+		if !ownerMatches {
+			continue
+		}
*** Update File: /Users/thomi/.codex/worktrees/c68d/entire-graph/internal/sem/parser.go
@@
-			cPlusPlusOwner: cPlusPlusDeclarationOwner(node, src, scope),
+			cPlusPlusOwners: cPlusPlusDeclarationOwners(node, src, scope),
@@
-// cPlusPlusDeclarationOwner returns the full lexical namespace/class owner of
-// an in-class declaration without changing its graph-qualified name or stable
-// ID. The latter intentionally uses the immediate container; this spelling is
-// private matching evidence for `acct::Outer::Ledger::Add` definitions.
-func cPlusPlusDeclarationOwner(node *sitter.Node, src []byte, scope string) string {
-	parts := []string{scope}
+// cPlusPlusDeclarationOwners returns legal lexical namespace/class owners of
+// an in-class declaration without changing its graph-qualified name or stable
+// ID. C++ lets an out-of-line definition omit inline namespace segments, so the
+// result includes bounded combinations of those omissions.
+func cPlusPlusDeclarationOwners(node *sitter.Node, src []byte, scope string) []string {
+	type segment struct {
+		name       string
+		inlineable bool
+	}
+	parts := []segment{{name: scope}}
 	skippedImmediate := false
@@
-		parts = append([]string{text}, parts...)
+		inlineable := false
+		if current.Type() == "namespace_definition" {
+			start, end := int(current.StartByte()), int(name.StartByte())
+			if start >= 0 && end > start && end <= len(src) {
+				inlineable = strings.Contains(string(src[start:end]), "inline")
+			}
+		}
+		parts = append([]segment{{name: text, inlineable: inlineable}}, parts...)
 	}
-	return strings.Join(parts, "::")
+	inlineCount := 0
+	for _, part := range parts {
+		if part.inlineable {
+			inlineCount++
+		}
+	}
+	// Bound aliases for adversarially deep nesting. Four inline namespaces
+	// already cover sixteen legal spellings; beyond that keep the full and
+	// fully-elided forms rather than growing exponentially.
+	masks := 1 << minInt(inlineCount, 4)
+	if inlineCount > 4 {
+		masks = 2
+	}
+	owners := make([]string, 0, masks)
+	for mask := 0; mask < masks; mask++ {
+		var names []string
+		inlineIndex := 0
+		for _, part := range parts {
+			omit := false
+			if part.inlineable {
+				if inlineCount <= 4 {
+					omit = mask&(1<<inlineIndex) != 0
+				} else {
+					omit = mask == 1
+				}
+				inlineIndex++
+			}
+			if !omit {
+				names = append(names, part.name)
+			}
+		}
+		owners = append(owners, strings.Join(names, "::"))
+	}
+	return owners
 }
*** End Patch";
text(await tools.apply_patch(patch));

